SELECT * FROM (
  SELECT ROWNUM AS RNUM, A.* FROM (
    SELECT 

         , O.MBR_ID
         , (SELECT COUNT(1) FROM TB_CLM_ITEM I WHERE I.CLM_NO = C.CLM_NO) AS ITEM_CNT
         , (SELECT NVL(SUM(I.ITEM_AMT), 0) FROM TB_CLM_ITEM I WHERE I.CLM_NO = C.CLM_NO) AS ITEM_AMT
      FROM TB_CLM C
      JOIN TB_ORD O ON O.ORD_NO = C.ORD_NO

      AND C.CLM_NO = #{CLM_NO}
      AND C.ORD_NO = #{ORD_NO}
      AND O.MBR_ID = #{MBR_ID}
      AND C.CLM_TYPE = #{CLM_TYPE}
      AND C.CLM_STAT = #{CLM_STAT}
      AND C.CLM_RSN = #{CLM_RSN}
      AND C.REQ_DT >= TO_DATE(#{FROM_DT}, 'YYYYMMDD')
      AND C.REQ_DT < TO_DATE(#{TO_DT}, 'YYYYMMDD') + 1

     ORDER BY C.REQ_DT DESC, C.CLM_NO DESC
  ) A WHERE ROWNUM <= 1000
)

SELECT 

  FROM TB_CLM C
 WHERE C.CLM_NO = #{clmNo}

SELECT COUNT(1)
  FROM TB_CLM_ITEM I
  JOIN TB_CLM C ON C.CLM_NO = I.CLM_NO
 WHERE I.ORD_NO = #{ORD_NO}
   AND I.ITEM_SEQ = #{ITEM_SEQ}
   AND C.CLM_STAT IN ('REQ', 'COL', 'CMP')

SELECT COUNT(1)
  FROM TB_CLM C
 WHERE C.ORD_NO = #{ORD_NO}
   AND C.CLM_TYPE = 'RTN'
   AND C.CLM_STAT = 'CMP'
   AND C.CLM_NO <> #{CLM_NO}

mapper.update:
UPDATE TB_CLM
   SET CLM_STAT = #{CLM_STAT}

     , COL_DT   = SYSDATE

     , UPD_DT   = SYSDATE
     , UPD_ID   = #{UPD_ID}
 WHERE CLM_NO = #{CLM_NO}

   AND CLM_STAT = #{BF_CLM_STAT}

UPDATE TB_CLM
   SET CLM_STAT       = 'CMP'
     , REFUND_AMT     = #{REFUND_AMT}
     , REFUND_PNT_AMT = #{REFUND_PNT_AMT}
     , CMPL_DT        = SYSDATE
     , UPD_DT         = SYSDATE
     , UPD_ID         = #{UPD_ID}
 WHERE CLM_NO = #{CLM_NO}
   AND CLM_STAT = 'COL'

UPDATE TB_CLM
   SET CLM_STAT = 'REJ'
     , REJ_RSN  = #{REJ_RSN}
     , CMPL_DT  = SYSDATE
     , UPD_DT   = SYSDATE
     , UPD_ID   = #{UPD_ID}
 WHERE CLM_NO = #{CLM_NO}
   AND CLM_STAT IN ('REQ', 'COL')

UPDATE TB_CLM_ITEM
   SET CPN_DC_SHARE_AMT = #{CPN_DC_SHARE_AMT}
     , REFUND_AMT       = #{REFUND_AMT}
 WHERE CLM_NO = #{CLM_NO}
   AND ITEM_SEQ = #{ITEM_SEQ}
